var DIAGRAMS={};
DIAGRAMS.conv_vs_zns={title:'Conventional versus zoned placement',cap:'Left: the device mixes hot and cold pages in the same erase blocks, so GC must copy live pages before it can erase. Right: the host puts data of one lifetime in one zone, so resetting a dead zone frees it with nothing to copy. In the top boxes amber is the host and blue is the device.',svg:`<svg viewBox="0 0 760 372" role="img" aria-label="Conventional SSD with mixed placement and garbage collection versus zoned placement with zone reset"><title>Conventional SSD with mixed placement and garbage collection versus zoned placement with zone reset</title><rect class="grp" x="10" y="32" width="360" height="304" rx="6" /><rect class="grp" x="390" y="32" width="360" height="304" rx="6" /><text class="h" x="190" y="24" text-anchor="middle">Conventional SSD</text><text class="h" x="570" y="24" text-anchor="middle">Zoned (ZNS) SSD</text><rect class="tl" x="30" y="48" width="320" height="44" rx="6" /><text class="s h" x="190" y="67" text-anchor="middle">Host: hot and cold data mixed</text><text class="xs d" x="190" y="83" text-anchor="middle">any LBA, any order, overwrite allowed</text><rect class="dl" x="30" y="112" width="320" height="44" rx="6" /><text class="s h" x="190" y="131" text-anchor="middle">Device FTL decides placement</text><text class="xs d" x="190" y="147" text-anchor="middle">page-level L2P, GC, large over-provisioning</text><rect class="box" x="30" y="182" width="93" height="30" rx="4" /><rect class="er" x="36" y="188" width="18" height="18" rx="2" /><text class="xs rd" x="45.0" y="201" text-anchor="middle">x</text><rect class="dl" x="57" y="188" width="18" height="18" rx="2" /><rect class="er" x="78" y="188" width="18" height="18" rx="2" /><text class="xs rd" x="87.0" y="201" text-anchor="middle">x</text><rect class="tl" x="99" y="188" width="18" height="18" rx="2" /><rect class="box" x="150" y="182" width="93" height="30" rx="4" /><rect class="dl" x="156" y="188" width="18" height="18" rx="2" /><rect class="er" x="177" y="188" width="18" height="18" rx="2" /><text class="xs rd" x="186.0" y="201" text-anchor="middle">x</text><rect class="er" x="198" y="188" width="18" height="18" rx="2" /><text class="xs rd" x="207.0" y="201" text-anchor="middle">x</text><rect class="dl" x="219" y="188" width="18" height="18" rx="2" /><line class="lnc" x1="76" y1="156" x2="76.0" y2="174.0"/><polygon class="ahc" points="76.0,182.0 71.5,173.0 80.5,173.0"/><line class="lnc" x1="196" y1="156" x2="196.0" y2="174.0"/><polygon class="ahc" points="196.0,182.0 191.5,173.0 200.5,173.0"/><text class="xs d" x="76" y="228" text-anchor="middle">block A</text><text class="xs d" x="196" y="228" text-anchor="middle">block B</text><rect class="box" x="150" y="268" width="93" height="30" rx="4" /><rect class="dl" x="156" y="274" width="18" height="18" rx="2" /><rect class="tl" x="177" y="274" width="18" height="18" rx="2" /><rect class="dl" x="198" y="274" width="18" height="18" rx="2" /><rect class="dl" x="219" y="274" width="18" height="18" rx="2" /><polyline class="lnr" points="76,236 76,282 142.0,282.0"/><polygon class="ahr" points="150.0,282.0 141.0,286.5 141.0,277.5"/><line class="lnr" x1="196" y1="236" x2="196.0" y2="260.0"/><polygon class="ahr" points="196.0,268.0 191.5,259.0 200.5,259.0"/><text class="xs d" x="196" y="314" text-anchor="middle">block C</text><text class="xs rd" x="255" y="282" text-anchor="start">GC copies</text><text class="xs rd" x="255" y="296" text-anchor="start">live pages,</text><text class="xs rd" x="255" y="310" text-anchor="start">erases A and B</text><rect class="tl" x="410" y="48" width="320" height="44" rx="6" /><text class="s h" x="570" y="67" text-anchor="middle">Host: places data by lifetime</text><text class="xs d" x="570" y="83" text-anchor="middle">writes sequentially at each write pointer</text><rect class="dl" x="410" y="112" width="320" height="44" rx="6" /><text class="s h" x="570" y="131" text-anchor="middle">Device: zone to erase-block map</text><text class="xs d" x="570" y="147" text-anchor="middle">no overwrites seen, so no remap and no GC</text><rect class="box" x="440" y="182" width="93" height="30" rx="4" /><rect class="er" x="446" y="188" width="18" height="18" rx="2" /><text class="xs rd" x="455.0" y="201" text-anchor="middle">x</text><rect class="er" x="467" y="188" width="18" height="18" rx="2" /><text class="xs rd" x="476.0" y="201" text-anchor="middle">x</text><rect class="er" x="488" y="188" width="18" height="18" rx="2" /><text class="xs rd" x="497.0" y="201" text-anchor="middle">x</text><rect class="er" x="509" y="188" width="18" height="18" rx="2" /><text class="xs rd" x="518.0" y="201" text-anchor="middle">x</text><rect class="box" x="600" y="182" width="93" height="30" rx="4" /><rect class="dl" x="606" y="188" width="18" height="18" rx="2" /><rect class="dl" x="627" y="188" width="18" height="18" rx="2" /><rect class="dl" x="648" y="188" width="18" height="18" rx="2" /><rect class="box" x="669" y="188" width="18" height="18" rx="2" /><line class="lnc" x1="486" y1="156" x2="486.0" y2="174.0"/><polygon class="ahc" points="486.0,182.0 481.5,173.0 490.5,173.0"/><line class="lnc" x1="646" y1="156" x2="646.0" y2="174.0"/><polygon class="ahc" points="646.0,182.0 641.5,173.0 650.5,173.0"/><text class="xs d" x="486" y="228" text-anchor="middle">Zone 0: hot, all stale</text><text class="xs d" x="646" y="228" text-anchor="middle">Zone 1: cold, live</text><rect class="box" x="440" y="268" width="93" height="30" rx="4" /><rect class="box" x="446" y="274" width="18" height="18" rx="2" /><rect class="box" x="467" y="274" width="18" height="18" rx="2" /><rect class="box" x="488" y="274" width="18" height="18" rx="2" /><rect class="box" x="509" y="274" width="18" height="18" rx="2" /><line class="lna" x1="486" y1="236" x2="486.0" y2="260.0"/><polygon class="ah" points="486.0,268.0 481.5,259.0 490.5,259.0"/><text class="xs ac" x="498" y="256" text-anchor="start">Reset Zone</text><text class="xs d" x="646" y="268" text-anchor="middle">untouched: no copying</text><text class="xs d" x="646" y="282" text-anchor="middle">while its data lives</text><text class="xs gr" x="570" y="314" text-anchor="middle">Zone 0 is empty again, zero pages copied</text><rect class="tl" x="200" y="348" width="16" height="14" rx="2" /><text class="xs" x="222" y="359" text-anchor="start">hot data</text><rect class="dl" x="300" y="348" width="16" height="14" rx="2" /><text class="xs" x="322" y="359" text-anchor="start">cold data</text><rect class="er" x="410" y="348" width="16" height="14" rx="2" /><text class="xs" x="432" y="359" text-anchor="start">stale (x)</text></svg>`};
DIAGRAMS.zonemodel={title:'Zone size, zone capacity and the write pointer',cap:'Each zone spans ZSZE LBAs but only the first ZCAP LBAs are usable. The write pointer marks the next LBA to write and only moves forward. Zone 2 has been filled to its capacity, so the zone is Full.',svg:`<svg viewBox="0 0 760 312" role="img" aria-label="LBA space divided into three zones with zone size, zone capacity and write pointer"><title>LBA space divided into three zones with zone size, zone capacity and write pointer</title><text class="xs d" x="40" y="16" text-anchor="start">LBA space of the namespace, in increasing LBA order, zones back to back</text><rect class="box" x="40" y="62" width="220" height="50" rx="3" /><rect class="box" x="260" y="62" width="220" height="50" rx="3" /><rect class="box" x="480" y="62" width="220" height="50" rx="3" /><rect class="dl" x="40" y="62" width="100" height="50" rx="3" /><rect class="grp" x="190" y="62" width="70" height="50" rx="0" /><text class="xs f" x="225.0" y="91" text-anchor="middle">not usable</text><text class="xs" x="90.0" y="91" text-anchor="middle">written</text><text class="s h" x="44" y="146" text-anchor="start">Zone 0</text><text class="xs d" x="44" y="130" text-anchor="start">ZSLBA = 0</text><line class="ln" x1="40" y1="112" x2="40" y2="120"/><rect class="dl" x="260" y="62" width="60" height="50" rx="3" /><rect class="grp" x="410" y="62" width="70" height="50" rx="0" /><text class="xs f" x="445.0" y="91" text-anchor="middle">not usable</text><text class="xs" x="290.0" y="91" text-anchor="middle">written</text><text class="s h" x="264" y="146" text-anchor="start">Zone 1</text><text class="xs d" x="264" y="130" text-anchor="start">ZSLBA = 1 x ZSZE</text><line class="ln" x1="260" y1="112" x2="260" y2="120"/><rect class="dl" x="480" y="62" width="150" height="50" rx="3" /><rect class="grp" x="630" y="62" width="70" height="50" rx="0" /><text class="xs f" x="665.0" y="91" text-anchor="middle">not usable</text><text class="xs" x="555.0" y="91" text-anchor="middle">written to capacity</text><text class="s h" x="484" y="146" text-anchor="start">Zone 2</text><text class="xs d" x="484" y="130" text-anchor="start">ZSLBA = 2 x ZSZE</text><line class="ln" x1="480" y1="112" x2="480" y2="120"/><line class="ln" x1="700" y1="112" x2="700" y2="120"/><line class="lna" x1="140" y1="34" x2="140.0" y2="54.0"/><polygon class="ah" points="140.0,62.0 135.5,53.0 144.5,53.0"/><text class="xs ac" x="148" y="32" text-anchor="start">WP of zone 0</text><line class="lna" x1="320" y1="34" x2="320.0" y2="54.0"/><polygon class="ah" points="320.0,62.0 315.5,53.0 324.5,53.0"/><text class="xs ac" x="328" y="32" text-anchor="start">WP of zone 1</text><text class="xs d" x="540" y="32" text-anchor="start">Full: WP no longer valid</text><line class="ln" x1="40" y1="178" x2="190" y2="178"/><line class="ln" x1="40" y1="172" x2="40" y2="178"/><line class="ln" x1="190" y1="172" x2="190" y2="178"/><text class="s gr" x="40" y="198" text-anchor="start">ZCAP: usable LBAs, counted from ZSLBA (at most ZSZE)</text><line class="ln" x1="40" y1="226" x2="260" y2="226"/><line class="ln" x1="40" y1="220" x2="40" y2="226"/><line class="ln" x1="260" y1="220" x2="260" y2="226"/><text class="s cy" x="40" y="246" text-anchor="start">ZSZE: LBAs the zone occupies in the address space</text><text class="xs d" x="40" y="282" text-anchor="start">Zone n starts at LBA n x ZSZE. ZSZE is the same for every zone. The write pointer moves only forward until Reset Zone.</text><text class="xs d" x="40" y="298" text-anchor="start">Blue is written, plain is writable up to ZCAP, dashed is the gap from ZCAP to ZSZE. Zone 2 is Full.</text></svg>`};
DIAGRAMS.zstates={title:'Zone state machine',cap:'Host commands are amber, controller-initiated moves are dashed. Blue states are the two open states, red states are degraded. Only transitions the question states outright are drawn; edge cases such as Close on an Empty zone are left out.',svg:`<svg viewBox="0 0 760 408" role="img" aria-label="Zone state machine with seven states and command-labelled transitions"><title>Zone state machine with seven states and command-labelled transitions</title><rect class="grp" x="10" y="96" width="610" height="196" rx="6" /><text class="xs f" x="22" y="112" text-anchor="start">Empty, open or Closed</text><rect class="grp" x="220" y="108" width="190" height="168" rx="6" /><text class="xs f" x="232" y="122" text-anchor="start">open zones</text><rect class="box" x="30" y="175" width="110" height="46" rx="6" /><text class="s h" x="85" y="203" text-anchor="middle">Empty</text><rect class="dl" x="235" y="132" width="160" height="40" rx="6" /><text class="s h" x="315" y="157" text-anchor="middle">Implicitly Opened</text><rect class="dl" x="235" y="224" width="160" height="40" rx="6" /><text class="s h" x="315" y="249" text-anchor="middle">Explicitly Opened</text><rect class="box" x="485" y="165" width="100" height="66" rx="6" /><text class="s h" x="535" y="202" text-anchor="middle">Closed</text><rect class="box" x="690" y="175" width="60" height="46" rx="6" /><text class="s h" x="720" y="203" text-anchor="middle">Full</text><rect class="er" x="140" y="12" width="130" height="44" rx="6" /><text class="s h" x="205" y="31" text-anchor="middle">Read Only</text><text class="xs d" x="205" y="46" text-anchor="middle">no writes</text><rect class="er" x="455" y="12" width="130" height="44" rx="6" /><text class="s h" x="520" y="31" text-anchor="middle">Offline</text><text class="xs d" x="520" y="46" text-anchor="middle">no reads or writes</text><line class="lna" x1="140" y1="185" x2="227.3" y2="158.3"/><polygon class="ah" points="235.0,156.0 227.7,162.9 225.1,154.3"/><text class="xs ac" x="190" y="157" text-anchor="end">Write, Append</text><line class="lna" x1="140" y1="211" x2="227.3" y2="234.0"/><polygon class="ah" points="235.0,236.0 225.2,238.1 227.4,229.4"/><text class="xs ac" x="196" y="246" text-anchor="end">Open Zone</text><line class="lna" x1="315" y1="172" x2="315.0" y2="216.0"/><polygon class="ah" points="315.0,224.0 310.5,215.0 319.5,215.0"/><text class="xs ac" x="323" y="202" text-anchor="start">Open Zone</text><line class="lna" x1="410" y1="198" x2="477.0" y2="198.0"/><polygon class="ah" points="485.0,198.0 476.0,202.5 476.0,193.5"/><text class="xs ac" x="447" y="190" text-anchor="middle">Close Zone</text><line class="lna" x1="485" y1="180" x2="402.8" y2="159.9"/><polygon class="ah" points="395.0,158.0 404.8,155.8 402.7,164.5"/><text class="xs ac" x="452" y="162" text-anchor="middle">Write</text><line class="lna" x1="485" y1="216" x2="402.8" y2="234.3"/><polygon class="ah" points="395.0,236.0 402.8,229.7 404.8,238.4"/><text class="xs ac" x="440" y="252" text-anchor="middle">Open Zone</text><line class="lna" x1="620" y1="198" x2="682.0" y2="198.0"/><polygon class="ah" points="690.0,198.0 681.0,202.5 681.0,193.5"/><text class="xs ac" x="655" y="190" text-anchor="middle">Finish Zone</text><line class="lna" x1="720" y1="221" x2="720" y2="316"/><line class="lna" x1="315" y1="276" x2="315" y2="316"/><line class="lna" x1="535" y1="231" x2="535" y2="316"/><polyline class="lna" points="720,316 85,316 85.0,229.0"/><polygon class="ah" points="85.0,221.0 89.5,230.0 80.5,230.0"/><text class="xs ac" x="400" y="338" text-anchor="middle">Reset Zone from open, Closed or Full: WP becomes ZSLBA, zone is Empty</text><line class="lna" x1="270" y1="34" x2="447.0" y2="34.0"/><polygon class="ah" points="455.0,34.0 446.0,38.5 446.0,29.5"/><text class="xs ac" x="362" y="26" text-anchor="middle">Offline Zone</text><text class="xs d" x="362" y="50" text-anchor="middle">host command</text><line class="lnd" x1="205" y1="96" x2="205.0" y2="64.0"/><polygon class="ahd" points="205.0,56.0 209.5,65.0 200.5,65.0"/><text class="xs d" x="213" y="80" text-anchor="start">controller</text><line class="lnd" x1="520" y1="96" x2="520.0" y2="64.0"/><polygon class="ahd" points="520.0,56.0 524.5,65.0 515.5,65.0"/><text class="xs d" x="528" y="80" text-anchor="start">controller</text><text class="xs d" x="20" y="366" text-anchor="start">Finish Zone works from Empty, open and Closed zones. A write that reaches ZCAP also takes an open zone to Full.</text><text class="xs d" x="20" y="381" text-anchor="start">The controller may close an Implicitly Opened zone to free an open resource. It never closes an Explicitly Opened one.</text><text class="xs d" x="20" y="396" text-anchor="start">Dashed: the controller moves a zone to Read Only or Offline for media reasons (source states not drawn). Offline is terminal.</text></svg>`};
DIAGRAMS.append={title:'Concurrent Zone Appends to one zone',cap:'Three appends to the same zone are in flight at once. The controller serializes them at the write pointer and hands each one its address in the completion entry. Amber is the host, blue is the controller and device.',svg:`<svg viewBox="0 0 760 372" role="img" aria-label="Three concurrent Zone Append commands to one zone, with the controller assigning LBAs returned in completion entries"><title>Three concurrent Zone Append commands to one zone, with the controller assigning LBAs returned in completion entries</title><rect class="tl" x="20" y="20" width="220" height="52" rx="6" /><text class="s h" x="130" y="40" text-anchor="middle">Append A</text><text class="xs d" x="130" y="58" text-anchor="middle">ZSLBA 0x1000, 8 LBAs</text><line class="lna" x1="60" y1="72" x2="60.0" y2="120.0"/><polygon class="ah" points="60.0,128.0 55.5,119.0 64.5,119.0"/><text class="xs ac" x="68" y="104" text-anchor="start">submit</text><line class="lnc" x1="140" y1="128" x2="140.0" y2="80.0"/><polygon class="ahc" points="140.0,72.0 144.5,81.0 135.5,81.0"/><text class="xs cy" x="148" y="96" text-anchor="start">CQE:</text><text class="xs cy" x="148" y="110" text-anchor="start">ALBA 0x1010</text><rect class="tl" x="270" y="20" width="220" height="52" rx="6" /><text class="s h" x="380" y="40" text-anchor="middle">Append B</text><text class="xs d" x="380" y="58" text-anchor="middle">ZSLBA 0x1000, 16 LBAs</text><line class="lna" x1="310" y1="72" x2="310.0" y2="120.0"/><polygon class="ah" points="310.0,128.0 305.5,119.0 314.5,119.0"/><text class="xs ac" x="318" y="104" text-anchor="start">submit</text><line class="lnc" x1="390" y1="128" x2="390.0" y2="80.0"/><polygon class="ahc" points="390.0,72.0 394.5,81.0 385.5,81.0"/><text class="xs cy" x="398" y="96" text-anchor="start">CQE:</text><text class="xs cy" x="398" y="110" text-anchor="start">ALBA 0x1000</text><rect class="tl" x="520" y="20" width="220" height="52" rx="6" /><text class="s h" x="630" y="40" text-anchor="middle">Append C</text><text class="xs d" x="630" y="58" text-anchor="middle">ZSLBA 0x1000, 8 LBAs</text><line class="lna" x1="560" y1="72" x2="560.0" y2="120.0"/><polygon class="ah" points="560.0,128.0 555.5,119.0 564.5,119.0"/><text class="xs ac" x="568" y="104" text-anchor="start">submit</text><line class="lnc" x1="640" y1="128" x2="640.0" y2="80.0"/><polygon class="ahc" points="640.0,72.0 644.5,81.0 635.5,81.0"/><text class="xs cy" x="648" y="96" text-anchor="start">CQE:</text><text class="xs cy" x="648" y="110" text-anchor="start">ALBA 0x1018</text><rect class="dl" x="20" y="128" width="720" height="48" rx="6" /><text class="s h" x="380" y="147" text-anchor="middle">Controller owns the write pointer: appends may arrive in any order, from any queue</text><text class="xs d" x="380" y="164" text-anchor="middle">here it happens to process B, then A, then C, and places each at the current WP</text><rect class="box" x="20" y="226" width="90" height="50" rx="3" /><text class="xs d" x="65" y="255" text-anchor="middle">earlier data</text><rect class="dl" x="110" y="226" width="180" height="50" rx="3" /><text class="s h" x="200" y="248" text-anchor="middle">B</text><text class="xs" x="200" y="265" text-anchor="middle">0x1000 - 0x100F</text><rect class="dl" x="290" y="226" width="90" height="50" rx="3" /><text class="s h" x="335" y="248" text-anchor="middle">A</text><text class="xs" x="335" y="265" text-anchor="middle">0x1010</text><rect class="dl" x="380" y="226" width="90" height="50" rx="3" /><text class="s h" x="425" y="248" text-anchor="middle">C</text><text class="xs" x="425" y="265" text-anchor="middle">0x1018</text><rect class="grp" x="470" y="226" width="270" height="50" rx="3" /><text class="xs f" x="605" y="255" text-anchor="middle">unwritten, up to ZCAP</text><line class="ln" x1="110" y1="276" x2="110" y2="284"/><text class="xs d" x="110" y="297" text-anchor="middle">0x1000</text><line class="ln" x1="290" y1="276" x2="290" y2="284"/><text class="xs d" x="290" y="297" text-anchor="middle">0x1010</text><line class="ln" x1="380" y1="276" x2="380" y2="284"/><text class="xs d" x="380" y="297" text-anchor="middle">0x1018</text><line class="ln" x1="470" y1="276" x2="470" y2="284"/><text class="xs d" x="470" y="297" text-anchor="middle">0x1020</text><text class="xs ac" x="110" y="313" text-anchor="middle">WP before</text><text class="xs ac" x="470" y="313" text-anchor="middle">WP after</text><line class="lnc" x1="200" y1="176" x2="200.0" y2="218.0"/><polygon class="ahc" points="200.0,226.0 195.5,217.0 204.5,217.0"/><text class="xs d" x="208" y="205" text-anchor="start">1st</text><line class="lnc" x1="335" y1="176" x2="335.0" y2="218.0"/><polygon class="ahc" points="335.0,226.0 330.5,217.0 339.5,217.0"/><text class="xs d" x="343" y="205" text-anchor="start">2nd</text><line class="lnc" x1="425" y1="176" x2="425.0" y2="218.0"/><polygon class="ahc" points="425.0,226.0 420.5,217.0 429.5,217.0"/><text class="xs d" x="433" y="205" text-anchor="start">3rd</text><text class="xs d" x="20" y="346" text-anchor="start">LBAs are illustrative. The host chose neither the order nor the addresses: it learns each address from the CQE.</text><text class="xs d" x="20" y="362" text-anchor="start">Every append names the zone start, not a write address, so none can fail because a peer moved the write pointer first.</text></svg>`};
DIAGRAMS.zoneres={title:'Active versus open zones',cap:'Two nested sets with two limits. Open zones (blue) are inside the active set, Closed zones are active but not open. Amber arrows show a zone moving between states and what each move takes or gives back.',svg:`<svg viewBox="0 0 760 392" role="img" aria-label="Nested active and open zone sets with MAR and MOR limits and zone state moves between them"><title>Nested active and open zone sets with MAR and MOR limits and zone state moves between them</title><rect class="grp" x="10" y="40" width="150" height="290" rx="6" /><text class="xs f" x="20" y="58" text-anchor="start">hold no resource</text><rect class="box" x="20" y="104" width="130" height="44" rx="6" /><text class="s h" x="85" y="131" text-anchor="middle">Empty</text><rect class="box" x="20" y="158" width="130" height="44" rx="6" /><text class="s h" x="85" y="185" text-anchor="middle">Full</text><rect class="er" x="20" y="212" width="130" height="44" rx="6" /><text class="s h" x="85" y="239" text-anchor="middle">Read Only</text><rect class="er" x="20" y="266" width="130" height="44" rx="6" /><text class="s h" x="85" y="293" text-anchor="middle">Offline</text><rect class="grp" x="230" y="40" width="520" height="290" rx="6" /><text class="s h ac" x="240" y="58" text-anchor="start">Active zones: count &lt;= MAR</text><rect class="grp" x="256" y="72" width="178" height="228" rx="6" /><text class="xs h cy" x="266" y="90" text-anchor="start">Open zones: count &lt;= MOR</text><rect class="dl" x="270" y="104" width="150" height="44" rx="6" /><text class="s h" x="345" y="131" text-anchor="middle">Implicitly Opened</text><rect class="dl" x="270" y="196" width="150" height="44" rx="6" /><text class="s h" x="345" y="223" text-anchor="middle">Explicitly Opened</text><rect class="box" x="620" y="140" width="115" height="90" rx="6" /><text class="s h" x="677" y="176" text-anchor="middle">Closed</text><text class="xs d" x="677" y="194" text-anchor="middle">keeps data</text><text class="xs d" x="677" y="207" text-anchor="middle">and WP</text><line class="lna" x1="150" y1="126" x2="262.0" y2="126.0"/><polygon class="ah" points="270.0,126.0 261.0,130.5 261.0,121.5"/><text class="xs ac" x="190" y="100" text-anchor="middle">Write or</text><text class="xs ac" x="190" y="111" text-anchor="middle">Open Zone</text><text class="xs d" x="190" y="141" text-anchor="middle">+1 active</text><text class="xs d" x="190" y="152" text-anchor="middle">+1 open</text><line class="lna" x1="345" y1="148" x2="345.0" y2="188.0"/><polygon class="ah" points="345.0,196.0 340.5,187.0 349.5,187.0"/><text class="xs ac" x="353" y="168" text-anchor="start">Open Zone</text><text class="xs d" x="353" y="181" text-anchor="start">(no change)</text><line class="lna" x1="434" y1="156" x2="612.0" y2="156.0"/><polygon class="ah" points="620.0,156.0 611.0,160.5 611.0,151.5"/><text class="xs ac" x="527" y="146" text-anchor="middle">Close Zone</text><text class="xs d" x="527" y="172" text-anchor="middle">frees 1 open, keeps 1 active</text><line class="lna" x1="620" y1="214" x2="442.0" y2="214.0"/><polygon class="ah" points="434.0,214.0 443.0,209.5 443.0,218.5"/><text class="xs ac" x="527" y="205" text-anchor="middle">Open Zone</text><text class="xs d" x="527" y="231" text-anchor="middle">needs 1 free open resource</text><text class="xs d" x="527" y="246" text-anchor="middle">a Write here opens it implicitly</text><text class="xs d" x="20" y="352" text-anchor="start">Open is a subset of active: every open zone also holds an active resource, and Closed zones are active but not open.</text><text class="xs d" x="20" y="367" text-anchor="start">Two independent budgets. Out of active resources blocks new zones from starting, out of open resources blocks new writers.</text><text class="xs d" x="20" y="382" text-anchor="start">Empty, Full, Read Only and Offline zones consume neither. Reaching Full, Reset or a controller fault releases what a zone held.</text></svg>`};
DIAGRAMS.zns_ftl={title:'A zone striped over dies and channels',cap:'The host sees only zone start, size, capacity, WP and state. Inside, a zone is a stripe of erase blocks over every die, so sequential writes use all channels in parallel and Reset Zone releases and erases the whole set.',svg:`<svg viewBox="0 0 760 398" role="img" aria-label="A zone mapped onto 12 dies over 6 channels as a stripe of 48 erase blocks that Reset Zone erases together"><title>A zone mapped onto 12 dies over 6 channels as a stripe of 48 erase blocks that Reset Zone erases together</title><rect class="tl" x="20" y="14" width="210" height="46" rx="6" /><text class="s h" x="125" y="33" text-anchor="middle">Zone k, as the host sees it</text><text class="xs d" x="125" y="50" text-anchor="middle">ZSLBA, ZSZE, ZCAP, WP, state</text><rect class="dl" x="290" y="14" width="230" height="46" rx="6" /><text class="s h" x="405" y="33" text-anchor="middle">Write buffer</text><text class="xs d" x="405" y="50" text-anchor="middle">cut into program units</text><rect class="dl" x="580" y="14" width="160" height="46" rx="6" /><text class="s h" x="660" y="33" text-anchor="middle">Per-zone record</text><text class="xs d" x="660" y="50" text-anchor="middle">state, WP, 48 blocks</text><line class="lna" x1="230" y1="37" x2="282.0" y2="37.0"/><polygon class="ah" points="290.0,37.0 281.0,41.5 281.0,32.5"/><line class="ln" x1="75" y1="84" x2="650" y2="84"/><line class="lnc" x1="405" y1="60" x2="405.0" y2="76.0"/><polygon class="ahc" points="405.0,84.0 400.5,75.0 409.5,75.0"/><line class="lnd" x1="660" y1="60" x2="660.0" y2="76.0"/><polygon class="ahd" points="660.0,84.0 655.5,75.0 664.5,75.0"/><line class="ln" x1="75" y1="84" x2="75" y2="96"/><rect class="dl" x="45" y="96" width="60" height="20" rx="6" /><text class="xs h" x="75" y="110" text-anchor="middle">CH0</text><line class="ln" x1="75" y1="116" x2="75" y2="256"/><line class="ln" x1="190" y1="84" x2="190" y2="96"/><rect class="dl" x="160" y="96" width="60" height="20" rx="6" /><text class="xs h" x="190" y="110" text-anchor="middle">CH1</text><line class="ln" x1="190" y1="116" x2="190" y2="256"/><line class="ln" x1="305" y1="84" x2="305" y2="96"/><rect class="dl" x="275" y="96" width="60" height="20" rx="6" /><text class="xs h" x="305" y="110" text-anchor="middle">CH2</text><line class="ln" x1="305" y1="116" x2="305" y2="256"/><line class="ln" x1="420" y1="84" x2="420" y2="96"/><rect class="dl" x="390" y="96" width="60" height="20" rx="6" /><text class="xs h" x="420" y="110" text-anchor="middle">CH3</text><line class="ln" x1="420" y1="116" x2="420" y2="256"/><line class="ln" x1="535" y1="84" x2="535" y2="96"/><rect class="dl" x="505" y="96" width="60" height="20" rx="6" /><text class="xs h" x="535" y="110" text-anchor="middle">CH4</text><line class="ln" x1="535" y1="116" x2="535" y2="256"/><line class="ln" x1="650" y1="84" x2="650" y2="96"/><rect class="dl" x="620" y="96" width="60" height="20" rx="6" /><text class="xs h" x="650" y="110" text-anchor="middle">CH5</text><line class="ln" x1="650" y1="116" x2="650" y2="256"/><rect class="box" x="25" y="126" width="100" height="58" rx="5" /><text class="xs" x="33" y="141" text-anchor="start">Die 0</text><text class="xs d" x="119" y="141" text-anchor="end">#1</text><rect class="pl" x="33" y="154" width="18" height="18" rx="2" /><rect class="pl" x="55" y="154" width="18" height="18" rx="2" /><rect class="pl" x="77" y="154" width="18" height="18" rx="2" /><rect class="pl" x="99" y="154" width="18" height="18" rx="2" /><rect class="box" x="140" y="126" width="100" height="58" rx="5" /><text class="xs" x="148" y="141" text-anchor="start">Die 0</text><text class="xs d" x="234" y="141" text-anchor="end">#2</text><rect class="pl" x="148" y="154" width="18" height="18" rx="2" /><rect class="pl" x="170" y="154" width="18" height="18" rx="2" /><rect class="pl" x="192" y="154" width="18" height="18" rx="2" /><rect class="pl" x="214" y="154" width="18" height="18" rx="2" /><rect class="box" x="255" y="126" width="100" height="58" rx="5" /><text class="xs" x="263" y="141" text-anchor="start">Die 0</text><text class="xs d" x="349" y="141" text-anchor="end">#3</text><rect class="pl" x="263" y="154" width="18" height="18" rx="2" /><rect class="pl" x="285" y="154" width="18" height="18" rx="2" /><rect class="pl" x="307" y="154" width="18" height="18" rx="2" /><rect class="pl" x="329" y="154" width="18" height="18" rx="2" /><rect class="box" x="370" y="126" width="100" height="58" rx="5" /><text class="xs" x="378" y="141" text-anchor="start">Die 0</text><text class="xs d" x="464" y="141" text-anchor="end">#4</text><rect class="pl" x="378" y="154" width="18" height="18" rx="2" /><rect class="pl" x="400" y="154" width="18" height="18" rx="2" /><rect class="pl" x="422" y="154" width="18" height="18" rx="2" /><rect class="pl" x="444" y="154" width="18" height="18" rx="2" /><rect class="box" x="485" y="126" width="100" height="58" rx="5" /><text class="xs" x="493" y="141" text-anchor="start">Die 0</text><text class="xs d" x="579" y="141" text-anchor="end">#5</text><rect class="pl" x="493" y="154" width="18" height="18" rx="2" /><rect class="pl" x="515" y="154" width="18" height="18" rx="2" /><rect class="pl" x="537" y="154" width="18" height="18" rx="2" /><rect class="pl" x="559" y="154" width="18" height="18" rx="2" /><rect class="box" x="600" y="126" width="100" height="58" rx="5" /><text class="xs" x="608" y="141" text-anchor="start">Die 0</text><text class="xs d" x="694" y="141" text-anchor="end">#6</text><rect class="pl" x="608" y="154" width="18" height="18" rx="2" /><rect class="pl" x="630" y="154" width="18" height="18" rx="2" /><rect class="pl" x="652" y="154" width="18" height="18" rx="2" /><rect class="pl" x="674" y="154" width="18" height="18" rx="2" /><rect class="box" x="25" y="198" width="100" height="58" rx="5" /><text class="xs" x="33" y="213" text-anchor="start">Die 1</text><text class="xs d" x="119" y="213" text-anchor="end">#7</text><rect class="pl" x="33" y="226" width="18" height="18" rx="2" /><rect class="pl" x="55" y="226" width="18" height="18" rx="2" /><rect class="pl" x="77" y="226" width="18" height="18" rx="2" /><rect class="pl" x="99" y="226" width="18" height="18" rx="2" /><rect class="box" x="140" y="198" width="100" height="58" rx="5" /><text class="xs" x="148" y="213" text-anchor="start">Die 1</text><text class="xs d" x="234" y="213" text-anchor="end">#8</text><rect class="pl" x="148" y="226" width="18" height="18" rx="2" /><rect class="pl" x="170" y="226" width="18" height="18" rx="2" /><rect class="pl" x="192" y="226" width="18" height="18" rx="2" /><rect class="pl" x="214" y="226" width="18" height="18" rx="2" /><rect class="box" x="255" y="198" width="100" height="58" rx="5" /><text class="xs" x="263" y="213" text-anchor="start">Die 1</text><text class="xs d" x="349" y="213" text-anchor="end">#9</text><rect class="pl" x="263" y="226" width="18" height="18" rx="2" /><rect class="pl" x="285" y="226" width="18" height="18" rx="2" /><rect class="pl" x="307" y="226" width="18" height="18" rx="2" /><rect class="pl" x="329" y="226" width="18" height="18" rx="2" /><rect class="box" x="370" y="198" width="100" height="58" rx="5" /><text class="xs" x="378" y="213" text-anchor="start">Die 1</text><text class="xs d" x="464" y="213" text-anchor="end">#10</text><rect class="pl" x="378" y="226" width="18" height="18" rx="2" /><rect class="pl" x="400" y="226" width="18" height="18" rx="2" /><rect class="pl" x="422" y="226" width="18" height="18" rx="2" /><rect class="pl" x="444" y="226" width="18" height="18" rx="2" /><rect class="box" x="485" y="198" width="100" height="58" rx="5" /><text class="xs" x="493" y="213" text-anchor="start">Die 1</text><text class="xs d" x="579" y="213" text-anchor="end">#11</text><rect class="pl" x="493" y="226" width="18" height="18" rx="2" /><rect class="pl" x="515" y="226" width="18" height="18" rx="2" /><rect class="pl" x="537" y="226" width="18" height="18" rx="2" /><rect class="pl" x="559" y="226" width="18" height="18" rx="2" /><rect class="box" x="600" y="198" width="100" height="58" rx="5" /><text class="xs" x="608" y="213" text-anchor="start">Die 1</text><text class="xs d" x="694" y="213" text-anchor="end">#12</text><rect class="pl" x="608" y="226" width="18" height="18" rx="2" /><rect class="pl" x="630" y="226" width="18" height="18" rx="2" /><rect class="pl" x="652" y="226" width="18" height="18" rx="2" /><rect class="pl" x="674" y="226" width="18" height="18" rx="2" /><line class="ln" x1="25" y1="270" x2="725" y2="270"/><line class="ln" x1="25" y1="264" x2="25" y2="270"/><line class="ln" x1="725" y1="264" x2="725" y2="270"/><text class="s gr" x="375" y="288" text-anchor="middle">One zone = one erase block per plane on every die = 12 dies x 4 planes = 48 blocks = 768 MiB</text><rect class="er" x="70" y="304" width="620" height="46" rx="6" /><text class="s h" x="380" y="324" text-anchor="middle">Reset Zone: the block list returns to the free pool and all 48 blocks are erased</text><text class="xs d" x="380" y="341" text-anchor="middle">No block holds data of any other zone, so nothing has to be copied first</text><text class="xs d" x="20" y="372" text-anchor="start">Example geometry: 6 channels x 2 dies, 4 planes per die, 16 MiB blocks. Layout and interleave are vendor specific.</text><text class="xs d" x="20" y="387" text-anchor="start">Green squares are erase blocks, four per die (one per plane). #n is the order program units visit the dies in this illustration.</text></svg>`};
DIAGRAMS.zrwa={title:'ZRWA window and write pointer',cap:'The window sits just above the committed write pointer. An explicit flush commits a range from WP up to the last LBA named, so WP moves up and the window slides with it. Amber is the writable window, blue is committed data, red is out of range.',svg:`<svg viewBox="0 0 760 372" role="img" aria-label="Zone Random Write Area window above the write pointer, before and after an explicit flush"><title>Zone Random Write Area window above the write pointer, before and after an explicit flush</title><text class="xs d" x="20" y="14" text-anchor="start">Offsets from ZSLBA increase to the right. WP is the committed write pointer.</text><text class="s h" x="20" y="38" text-anchor="start">1. Before</text><line class="ln" x1="120" y1="56" x2="320" y2="56"/><line class="ln" x1="120" y1="56" x2="120" y2="62"/><line class="ln" x1="320" y1="56" x2="320" y2="62"/><text class="xs ac" x="220.0" y="50" text-anchor="middle">ZRWASZ</text><line class="ln" x1="320" y1="56" x2="520" y2="56"/><line class="ln" x1="320" y1="56" x2="320" y2="62"/><line class="ln" x1="520" y1="56" x2="520" y2="62"/><text class="xs d" x="420.0" y="50" text-anchor="middle">second region: size VERIFY</text><rect class="dl" x="20" y="66" width="100" height="50" rx="3" /><text class="xs h" x="70.0" y="88" text-anchor="middle">committed</text><text class="xs d" x="70.0" y="104" text-anchor="middle">no overwrite</text><rect class="tl" x="120" y="66" width="200" height="50" rx="3" /><text class="s h" x="220" y="88" text-anchor="middle">ZRWA window</text><text class="xs d" x="220" y="104" text-anchor="middle">any order, overwrite ok</text><rect class="grp" x="320" y="66" width="200" height="50" rx="3" /><text class="s h" x="420" y="88" text-anchor="middle">second region</text><text class="xs d" x="420" y="104" text-anchor="middle">a write ending here flushes</text><rect class="er" x="520" y="66" width="220" height="50" rx="3" /><text class="s h" x="630.0" y="88" text-anchor="middle">beyond</text><text class="xs d" x="630.0" y="104" text-anchor="middle">Zone Invalid Write</text><line class="lna" x1="120" y1="142" x2="120.0" y2="124.0"/><polygon class="ah" points="120.0,116.0 124.5,125.0 115.5,125.0"/><text class="xs ac" x="128" y="136" text-anchor="start">WP</text><line class="lna" x1="170" y1="116" x2="170.0" y2="218.0"/><polygon class="ah" points="170.0,226.0 165.5,217.0 174.5,217.0"/><text class="xs ac" x="182" y="150" text-anchor="start">Flush Explicit ZRWA (Zone Send Action 11h)</text><text class="xs d" x="182" y="165" text-anchor="start">SLBA = last LBA to commit: [WP, SLBA] is committed,</text><text class="xs d" x="182" y="178" text-anchor="start">WP becomes SLBA + 1 and the window slides up</text><text class="s h" x="20" y="210" text-anchor="start">2. After the explicit flush</text><line class="ln" x1="200" y1="216" x2="400" y2="216"/><line class="ln" x1="200" y1="216" x2="200" y2="222"/><line class="ln" x1="400" y1="216" x2="400" y2="222"/><text class="xs ac" x="300.0" y="210" text-anchor="middle">ZRWASZ</text><line class="ln" x1="400" y1="216" x2="600" y2="216"/><line class="ln" x1="400" y1="216" x2="400" y2="222"/><line class="ln" x1="600" y1="216" x2="600" y2="222"/><text class="xs d" x="500.0" y="210" text-anchor="middle">second region: size VERIFY</text><rect class="dl" x="20" y="226" width="180" height="50" rx="3" /><text class="xs h" x="110.0" y="248" text-anchor="middle">committed</text><text class="xs d" x="110.0" y="264" text-anchor="middle">no overwrite</text><rect class="tl" x="200" y="226" width="200" height="50" rx="3" /><text class="s h" x="300" y="248" text-anchor="middle">ZRWA window</text><text class="xs d" x="300" y="264" text-anchor="middle">any order, overwrite ok</text><rect class="grp" x="400" y="226" width="200" height="50" rx="3" /><text class="s h" x="500" y="248" text-anchor="middle">second region</text><text class="xs d" x="500" y="264" text-anchor="middle">a write ending here flushes</text><rect class="er" x="600" y="226" width="140" height="50" rx="3" /><text class="s h" x="670.0" y="248" text-anchor="middle">beyond</text><text class="xs d" x="670.0" y="264" text-anchor="middle">Zone Invalid Write</text><line class="lna" x1="200" y1="302" x2="200.0" y2="284.0"/><polygon class="ah" points="200.0,276.0 204.5,285.0 195.5,285.0"/><text class="xs ac" x="208" y="296" text-anchor="start">new WP</text><text class="xs d" x="20" y="330" text-anchor="start">Committed data is sequential-only. Writes inside the window may come in any order and may overwrite until committed.</text><text class="xs d" x="20" y="345" text-anchor="start">A write that reaches into the second region also moves WP (implicit flush), with no flush command from the host.</text><text class="xs d" x="20" y="360" text-anchor="start">VERIFY: size of the second region, implicit-flush rounding (ZRWAFG units), and alignment rules for writes and flush ranges.</text></svg>`};
DIAGRAMS.zmgmt={title:'Zone management actions',cap:'Each Send action moves one zone from a set of source states to a target state; with Select All the controller applies it to every zone in those source states and skips the rest without error. Receive reads zone state back, optionally filtered by state.',svg:`<svg viewBox="0 0 760 398" role="img" aria-label="Zone Management Send actions with source and target states, Select All scope, and Zone Management Receive options"><title>Zone Management Send actions with source and target states, Select All scope, and Zone Management Receive options</title><rect class="tl" x="20" y="12" width="720" height="46" rx="6" /><text class="h" x="380" y="31" text-anchor="middle">Zone Management Send (opcode 79h)</text><text class="xs d" x="380" y="48" text-anchor="middle">CDW10-11 SLBA = zone start LBA | CDW13 bits 7:0 ZSA, bit 8 Select All</text><rect class="dl" x="20" y="72" width="56" height="24" rx="2" /><text class="s h" x="28" y="88" text-anchor="start">ZSA</text><rect class="dl" x="76" y="72" width="176" height="24" rx="2" /><text class="s h" x="84" y="88" text-anchor="start">Action</text><rect class="dl" x="252" y="72" width="256" height="24" rx="2" /><text class="s h" x="260" y="88" text-anchor="start">One zone: source -&gt; target</text><rect class="dl" x="508" y="72" width="232" height="24" rx="2" /><text class="s h" x="516" y="88" text-anchor="start">Select All acts on</text><rect class="box" x="20" y="96" width="56" height="24" rx="2" /><text class="xs h" x="28" y="112" text-anchor="start">01h</text><rect class="box" x="76" y="96" width="176" height="24" rx="2" /><text class="xs" x="84" y="112" text-anchor="start">Close Zone</text><rect class="box" x="252" y="96" width="256" height="24" rx="2" /><text class="xs" x="260" y="112" text-anchor="start">Open -&gt; Closed</text><rect class="box" x="508" y="96" width="232" height="24" rx="2" /><text class="xs" x="516" y="112" text-anchor="start">Implicitly + Explicitly Open</text><rect class="box" x="20" y="120" width="56" height="24" rx="2" /><text class="xs h" x="28" y="136" text-anchor="start">02h</text><rect class="box" x="76" y="120" width="176" height="24" rx="2" /><text class="xs" x="84" y="136" text-anchor="start">Finish Zone</text><rect class="box" x="252" y="120" width="256" height="24" rx="2" /><text class="xs" x="260" y="136" text-anchor="start">Empty, Open, Closed -&gt; Full</text><rect class="box" x="508" y="120" width="232" height="24" rx="2" /><text class="xs" x="516" y="136" text-anchor="start">Open, Closed</text><rect class="box" x="20" y="144" width="56" height="24" rx="2" /><text class="xs h" x="28" y="160" text-anchor="start">03h</text><rect class="box" x="76" y="144" width="176" height="24" rx="2" /><text class="xs" x="84" y="160" text-anchor="start">Open Zone</text><rect class="box" x="252" y="144" width="256" height="24" rx="2" /><text class="xs" x="260" y="160" text-anchor="start">Empty, Imp. Open, Closed -&gt; Exp. Open</text><rect class="box" x="508" y="144" width="232" height="24" rx="2" /><text class="xs" x="516" y="160" text-anchor="start">Closed (never Empty)</text><rect class="box" x="20" y="168" width="56" height="24" rx="2" /><text class="xs h" x="28" y="184" text-anchor="start">04h</text><rect class="box" x="76" y="168" width="176" height="24" rx="2" /><text class="xs" x="84" y="184" text-anchor="start">Reset Zone</text><rect class="box" x="252" y="168" width="256" height="24" rx="2" /><text class="xs" x="260" y="184" text-anchor="start">Open, Closed, Full -&gt; Empty, WP = ZSLBA</text><rect class="box" x="508" y="168" width="232" height="24" rx="2" /><text class="xs" x="516" y="184" text-anchor="start">Open, Closed, Full</text><rect class="box" x="20" y="192" width="56" height="24" rx="2" /><text class="xs h" x="28" y="208" text-anchor="start">05h</text><rect class="box" x="76" y="192" width="176" height="24" rx="2" /><text class="xs" x="84" y="208" text-anchor="start">Offline Zone</text><rect class="box" x="252" y="192" width="256" height="24" rx="2" /><text class="xs" x="260" y="208" text-anchor="start">Read Only -&gt; Offline</text><rect class="box" x="508" y="192" width="232" height="24" rx="2" /><text class="xs" x="516" y="208" text-anchor="start">Read Only</text><rect class="box" x="20" y="216" width="56" height="24" rx="2" /><text class="xs h" x="28" y="232" text-anchor="start">10h</text><rect class="box" x="76" y="216" width="176" height="24" rx="2" /><text class="xs" x="84" y="232" text-anchor="start">Set Zone Descr. Ext.</text><rect class="box" x="252" y="216" width="256" height="24" rx="2" /><text class="xs" x="260" y="232" text-anchor="start">Empty -&gt; Closed, writes extension data</text><rect class="box" x="508" y="216" width="232" height="24" rx="2" /><text class="xs" x="516" y="232" text-anchor="start">not allowed</text><rect class="box" x="20" y="240" width="56" height="24" rx="2" /><text class="xs h" x="28" y="256" text-anchor="start">11h</text><rect class="box" x="76" y="240" width="176" height="24" rx="2" /><text class="xs" x="84" y="256" text-anchor="start">Flush Explicit ZRWA</text><rect class="box" x="252" y="240" width="256" height="24" rx="2" /><text class="xs" x="260" y="256" text-anchor="start">commits ZRWA data up to SLBA</text><rect class="box" x="508" y="240" width="232" height="24" rx="2" /><text class="xs" x="516" y="256" text-anchor="start">see ZRWA module</text><rect class="dl" x="20" y="280" width="720" height="104" rx="6" /><text class="h" x="380" y="300" text-anchor="middle">Zone Management Receive (opcode 7Ah)</text><text class="xs" x="36" y="322" text-anchor="start">ZRA 00h Report Zones, 01h Extended Report Zones (descriptors plus extensions)</text><text class="xs" x="36" y="340" text-anchor="start">ZRAS filter: 00h all, 01h Empty, 02h Imp. Open, 03h Exp. Open, 04h Closed,</text><text class="xs" x="36" y="356" text-anchor="start">             05h Full, 06h Read Only, 07h Offline (ZNS 1.4 numbering)</text><text class="xs d" x="36" y="374" text-anchor="start">Partial Report = 1: Number of Zones counts only the descriptors returned</text></svg>`};
DIAGRAMS.zdesc={title:'Report Zones data layout',cap:"A 64-byte header carries the number of zones, then one 64-byte descriptor per zone; Extended Report Zones adds each zone's extension after its descriptor. Byte 1 holds the state in its upper nibble, and bytes 8 to 31 hold capacity, start LBA and write pointer.",svg:`<svg viewBox="0 0 760 390" role="img" aria-label="Report Zones header, zone descriptor byte layout, zone state codes and zone attribute bits"><title>Report Zones header, zone descriptor byte layout, zone state codes and zone attribute bits</title><text class="s h" x="20" y="18" text-anchor="start">Report Zones data (all values little-endian, addresses in LBAs)</text><rect class="tl" x="20" y="28" width="140" height="44" rx="3" /><text class="s h" x="90" y="47" text-anchor="middle">Header 64 B</text><text class="xs d" x="90" y="63" text-anchor="middle">bytes 7:0 = Nr Zones</text><rect class="dl" x="166" y="28" width="140" height="44" rx="3" /><text class="s h" x="236" y="47" text-anchor="middle">Descriptor 0</text><text class="xs d" x="236" y="63" text-anchor="middle">64 B</text><rect class="grp" x="312" y="28" width="110" height="44" rx="3" /><text class="s h" x="367" y="47" text-anchor="middle">Extension 0</text><text class="xs d" x="367" y="63" text-anchor="middle">ZDES x 64 B</text><rect class="dl" x="428" y="28" width="140" height="44" rx="3" /><text class="s h" x="498" y="47" text-anchor="middle">Descriptor 1</text><text class="xs d" x="498" y="63" text-anchor="middle">64 B</text><rect class="grp" x="574" y="28" width="110" height="44" rx="3" /><text class="s h" x="629" y="47" text-anchor="middle">Extension 1</text><text class="xs d" x="629" y="63" text-anchor="middle">ZDES x 64 B</text><text class="h" x="712" y="55" text-anchor="middle">...</text><text class="xs d" x="367" y="88" text-anchor="middle">extensions only in Extended Report Zones</text><text class="s h" x="20" y="118" text-anchor="start">Each zone descriptor (64 bytes), by byte offset</text><rect class="dl" x="20" y="132" width="70" height="50" rx="2" /><text class="xs d" x="55.0" y="148" text-anchor="middle">0</text><text class="s h" x="55.0" y="164" text-anchor="middle">ZT</text><text class="xs d" x="55.0" y="177" text-anchor="middle">type 3:0</text><rect class="dl" x="90" y="132" width="70" height="50" rx="2" /><text class="xs d" x="125.0" y="148" text-anchor="middle">1</text><text class="s h" x="125.0" y="164" text-anchor="middle">ZS</text><text class="xs d" x="125.0" y="177" text-anchor="middle">state 7:4</text><rect class="dl" x="160" y="132" width="70" height="50" rx="2" /><text class="xs d" x="195.0" y="148" text-anchor="middle">2</text><text class="s h" x="195.0" y="164" text-anchor="middle">ZA</text><text class="xs d" x="195.0" y="177" text-anchor="middle">attributes</text><rect class="box" x="230" y="132" width="90" height="50" rx="2" /><text class="xs d" x="275.0" y="148" text-anchor="middle">7:3</text><text class="s h" x="275.0" y="164" text-anchor="middle">rsvd</text><rect class="dl" x="320" y="132" width="130" height="50" rx="2" /><text class="xs d" x="385.0" y="148" text-anchor="middle">15:8</text><text class="s h" x="385.0" y="164" text-anchor="middle">ZCAP</text><text class="xs d" x="385.0" y="177" text-anchor="middle">zone capacity</text><rect class="dl" x="450" y="132" width="130" height="50" rx="2" /><text class="xs d" x="515.0" y="148" text-anchor="middle">23:16</text><text class="s h" x="515.0" y="164" text-anchor="middle">ZSLBA</text><text class="xs d" x="515.0" y="177" text-anchor="middle">zone start</text><rect class="dl" x="580" y="132" width="100" height="50" rx="2" /><text class="xs d" x="630.0" y="148" text-anchor="middle">31:24</text><text class="s h" x="630.0" y="164" text-anchor="middle">WP</text><text class="xs d" x="630.0" y="177" text-anchor="middle">write pointer</text><rect class="box" x="680" y="132" width="60" height="50" rx="2" /><text class="xs d" x="710.0" y="148" text-anchor="middle">63:32</text><text class="s h" x="710.0" y="164" text-anchor="middle">rsvd</text><rect class="dl" x="20" y="200" width="90" height="22" rx="2" /><text class="s h" x="28" y="216" text-anchor="start">ZS value</text><rect class="dl" x="110" y="200" width="170" height="22" rx="2" /><text class="s h" x="118" y="216" text-anchor="start">Zone state</text><rect class="box" x="20" y="222" width="90" height="22" rx="2" /><text class="xs h" x="28" y="238" text-anchor="start">1h</text><rect class="box" x="110" y="222" width="170" height="22" rx="2" /><text class="xs" x="118" y="238" text-anchor="start">Empty</text><rect class="box" x="20" y="244" width="90" height="22" rx="2" /><text class="xs h" x="28" y="260" text-anchor="start">2h</text><rect class="box" x="110" y="244" width="170" height="22" rx="2" /><text class="xs" x="118" y="260" text-anchor="start">Implicitly Opened</text><rect class="box" x="20" y="266" width="90" height="22" rx="2" /><text class="xs h" x="28" y="282" text-anchor="start">3h</text><rect class="box" x="110" y="266" width="170" height="22" rx="2" /><text class="xs" x="118" y="282" text-anchor="start">Explicitly Opened</text><rect class="box" x="20" y="288" width="90" height="22" rx="2" /><text class="xs h" x="28" y="304" text-anchor="start">4h</text><rect class="box" x="110" y="288" width="170" height="22" rx="2" /><text class="xs" x="118" y="304" text-anchor="start">Closed</text><rect class="box" x="20" y="310" width="90" height="22" rx="2" /><text class="xs h" x="28" y="326" text-anchor="start">Dh</text><rect class="box" x="110" y="310" width="170" height="22" rx="2" /><text class="xs" x="118" y="326" text-anchor="start">Read Only</text><rect class="box" x="20" y="332" width="90" height="22" rx="2" /><text class="xs h" x="28" y="348" text-anchor="start">Eh</text><rect class="box" x="110" y="332" width="170" height="22" rx="2" /><text class="xs" x="118" y="348" text-anchor="start">Full</text><rect class="box" x="20" y="354" width="90" height="22" rx="2" /><text class="xs h" x="28" y="370" text-anchor="start">Fh</text><rect class="box" x="110" y="354" width="170" height="22" rx="2" /><text class="xs" x="118" y="370" text-anchor="start">Offline</text><rect class="dl" x="300" y="200" width="70" height="22" rx="2" /><text class="s h" x="308" y="216" text-anchor="start">ZA bit</text><rect class="dl" x="370" y="200" width="250" height="22" rx="2" /><text class="s h" x="378" y="216" text-anchor="start">Meaning</text><rect class="box" x="300" y="222" width="70" height="22" rx="2" /><text class="xs h" x="308" y="238" text-anchor="start">0</text><rect class="box" x="370" y="222" width="250" height="22" rx="2" /><text class="xs" x="378" y="238" text-anchor="start">ZFC: finished by controller</text><rect class="box" x="300" y="244" width="70" height="22" rx="2" /><text class="xs h" x="308" y="260" text-anchor="start">1</text><rect class="box" x="370" y="244" width="250" height="22" rx="2" /><text class="xs" x="378" y="260" text-anchor="start">FZR: finish recommended</text><rect class="box" x="300" y="266" width="70" height="22" rx="2" /><text class="xs h" x="308" y="282" text-anchor="start">2</text><rect class="box" x="370" y="266" width="250" height="22" rx="2" /><text class="xs" x="378" y="282" text-anchor="start">RZR: reset recommended</text><rect class="box" x="300" y="288" width="70" height="22" rx="2" /><text class="xs h" x="308" y="304" text-anchor="start">3</text><rect class="box" x="370" y="288" width="250" height="22" rx="2" /><text class="xs" x="378" y="304" text-anchor="start">ZRWAV: ZRWA valid</text><rect class="box" x="300" y="310" width="70" height="22" rx="2" /><text class="xs h" x="308" y="326" text-anchor="start">7</text><rect class="box" x="370" y="310" width="250" height="22" rx="2" /><text class="xs" x="378" y="326" text-anchor="start">ZDEV: extension valid</text><text class="xs h" x="690" y="214" text-anchor="middle">ZT 2h =</text><text class="xs d" x="690" y="228" text-anchor="middle">Sequential</text><text class="xs d" x="690" y="241" text-anchor="middle">Write Required</text><text class="xs h" x="690" y="272" text-anchor="middle">WP is only</text><text class="xs d" x="690" y="286" text-anchor="middle">meaningful for</text><text class="xs d" x="690" y="299" text-anchor="middle">Empty, Open,</text><text class="xs d" x="690" y="312" text-anchor="middle">Closed zones</text></svg>`};
DIAGRAMS.zwrite={title:'Write outcome by zone state and address',cap:'A write succeeds only in a writable zone, exactly at the write pointer, within zone capacity and with an active and open slot available. Each failed check has its own zone status code, and a rejected write changes nothing.',svg:`<svg viewBox="0 0 760 424" role="img" aria-label="Decision flow for a Write to a zone with the zone status code returned at each failed check"><title>Decision flow for a Write to a zone with the zone status code returned at each failed check</title><rect class="tl" x="270" y="10" width="220" height="40" rx="6" /><text class="h" x="380" y="27" text-anchor="middle">Write (SLBA, NLB)</text><text class="xs d" x="380" y="42" text-anchor="middle">to one zone</text><line class="lna" x1="380" y1="50" x2="380.0" y2="64.0"/><polygon class="ah" points="380.0,72.0 375.5,63.0 384.5,63.0"/><rect class="box" x="270" y="72" width="220" height="36" rx="6" /><text class="s h" x="380" y="94" text-anchor="middle">Zone state?</text><polyline class="lnr" points="270,90 252,90 252,136 198.0,136.0"/><polygon class="ahr" points="190.0,136.0 199.0,131.5 199.0,140.5"/><text class="xs rd" x="221" y="130" text-anchor="middle">Full</text><rect class="er" x="20" y="118" width="170" height="36" rx="6" /><text class="s h" x="105" y="134" text-anchor="middle">Zone Is Full</text><text class="xs d" x="105" y="148" text-anchor="middle">SC B9h</text><polyline class="lnr" points="270,90 252,90 252,182 198.0,182.0"/><polygon class="ahr" points="190.0,182.0 199.0,177.5 199.0,186.5"/><text class="xs rd" x="221" y="176" text-anchor="middle">Read Only</text><rect class="er" x="20" y="164" width="170" height="36" rx="6" /><text class="s h" x="105" y="180" text-anchor="middle">Zone Is Read Only</text><text class="xs d" x="105" y="194" text-anchor="middle">SC BAh</text><polyline class="lnr" points="270,90 252,90 252,228 198.0,228.0"/><polygon class="ahr" points="190.0,228.0 199.0,223.5 199.0,232.5"/><text class="xs rd" x="221" y="222" text-anchor="middle">Offline</text><rect class="er" x="20" y="210" width="170" height="36" rx="6" /><text class="s h" x="105" y="226" text-anchor="middle">Zone Is Offline</text><text class="xs d" x="105" y="240" text-anchor="middle">SC BBh</text><line class="lna" x1="380" y1="108" x2="380.0" y2="132.0"/><polygon class="ah" points="380.0,140.0 375.5,131.0 384.5,131.0"/><text class="xs ac" x="388" y="128" text-anchor="start">Empty, Open, Closed</text><rect class="box" x="270" y="140" width="220" height="36" rx="6" /><text class="s h" x="380" y="162" text-anchor="middle">SLBA == write pointer?</text><line class="lnr" x1="490" y1="158" x2="536.0" y2="158.0"/><polygon class="ahr" points="544.0,158.0 535.0,162.5 535.0,153.5"/><text class="xs rd" x="498" y="151" text-anchor="start">no</text><rect class="er" x="544" y="140" width="196" height="36" rx="6" /><text class="s h" x="642" y="156" text-anchor="middle">Zone Invalid Write</text><text class="xs d" x="642" y="170" text-anchor="middle">SC BCh</text><line class="lna" x1="380" y1="176" x2="380.0" y2="196.0"/><polygon class="ah" points="380.0,204.0 375.5,195.0 384.5,195.0"/><text class="xs ac" x="388" y="194" text-anchor="start">yes</text><rect class="box" x="270" y="204" width="220" height="36" rx="6" /><text class="s h" x="380" y="220" text-anchor="middle">SLBA + NLB within</text><text class="s h" x="380" y="234" text-anchor="middle">ZSLBA + ZCAP?</text><line class="lnr" x1="490" y1="222" x2="536.0" y2="222.0"/><polygon class="ahr" points="544.0,222.0 535.0,226.5 535.0,217.5"/><text class="xs rd" x="498" y="215" text-anchor="start">no</text><rect class="er" x="544" y="204" width="196" height="36" rx="6" /><text class="s h" x="642" y="220" text-anchor="middle">Zone Boundary Error</text><text class="xs d" x="642" y="234" text-anchor="middle">SC B8h</text><line class="lna" x1="380" y1="240" x2="380.0" y2="260.0"/><polygon class="ah" points="380.0,268.0 375.5,259.0 384.5,259.0"/><text class="xs ac" x="388" y="258" text-anchor="start">yes</text><rect class="box" x="270" y="268" width="220" height="36" rx="6" /><text class="s h" x="380" y="284" text-anchor="middle">Empty or Closed: active</text><text class="s h" x="380" y="298" text-anchor="middle">and open slots free?</text><line class="lnr" x1="490" y1="286" x2="536.0" y2="286.0"/><polygon class="ahr" points="544.0,286.0 535.0,290.5 535.0,281.5"/><text class="xs rd" x="498" y="279" text-anchor="start">no</text><rect class="er" x="544" y="268" width="196" height="36" rx="6" /><text class="s h" x="642" y="284" text-anchor="middle">Too Many Active / Open</text><text class="xs d" x="642" y="298" text-anchor="middle">SC BDh / BEh</text><line class="lna" x1="380" y1="304" x2="380.0" y2="324.0"/><polygon class="ah" points="380.0,332.0 375.5,323.0 384.5,323.0"/><text class="xs ac" x="388" y="322" text-anchor="start">yes</text><rect class="pl" x="250" y="332" width="260" height="44" rx="6" /><text class="s h" x="380" y="350" text-anchor="middle">Success: WP += NLB</text><text class="xs d" x="380" y="366" text-anchor="middle">zone Open, or Full at capacity</text><text class="xs d" x="20" y="300" text-anchor="start">Rejected writes leave</text><text class="xs d" x="20" y="313" text-anchor="start">state and WP unchanged.</text><text class="xs d" x="20" y="340" text-anchor="start">All codes: SCT 1h</text><text class="xs d" x="20" y="353" text-anchor="start">(command specific).</text><text class="xs d" x="380" y="398" text-anchor="middle">The check order drawn is one reasonable order. ZNS 1.4 defines no precedence when several faults</text><text class="xs d" x="380" y="412" text-anchor="middle">apply at once, so a validator accepts the set of possible statuses for multi-fault writes (7.11).</text></svg>`};
DIAGRAMS.zstack={title:'Linux host stack for a ZNS namespace',cap:'Every layer above the device must keep writes sequential per zone; the block layer orders them and tracks the write pointer, and the device only enforces the rules with status codes. Passthrough and user-space drivers skip the ordering layers.',svg:`<svg viewBox="0 0 760 388" role="img" aria-label="Linux layers from application to ZNS SSD with examples and each layer's job, plus passthrough bypass paths"><title>Linux layers from application to ZNS SSD with examples and each layer's job, plus passthrough bypass paths</title><text class="s h" x="128" y="18" text-anchor="middle">Layer</text><text class="s h" x="328" y="18" text-anchor="middle">Examples</text><text class="s h" x="588" y="18" text-anchor="middle">Job for sequential writes</text><rect class="tl" x="60" y="28" width="136" height="40" rx="6" /><text class="s h" x="128" y="52" text-anchor="middle">Application</text><rect class="box" x="206" y="28" width="244" height="40" rx="6" /><text class="xs" x="328" y="52" text-anchor="middle">RocksDB + ZenFS, log engines, fio zbd</text><rect class="box" x="460" y="28" width="280" height="40" rx="6" /><text class="xs" x="600" y="52" text-anchor="middle">picks zone, tracks WP, resets, recovers</text><line class="lna" x1="128" y1="68" x2="128.0" y2="72.0"/><polygon class="ah" points="128.0,80.0 123.5,71.0 132.5,71.0"/><rect class="tl" x="60" y="80" width="136" height="40" rx="6" /><text class="s h" x="128" y="104" text-anchor="middle">File system</text><rect class="box" x="206" y="80" width="244" height="40" rx="6" /><text class="xs" x="328" y="104" text-anchor="middle">zonefs, f2fs, btrfs zoned</text><rect class="box" x="460" y="80" width="280" height="40" rx="6" /><text class="xs" x="600" y="104" text-anchor="middle">append-only allocation and reclaim</text><line class="lna" x1="128" y1="120" x2="128.0" y2="124.0"/><polygon class="ah" points="128.0,132.0 123.5,123.0 132.5,123.0"/><rect class="tl" x="60" y="132" width="136" height="40" rx="6" /><text class="s h" x="128" y="156" text-anchor="middle">Device mapper</text><rect class="box" x="206" y="132" width="244" height="40" rx="6" /><text class="xs" x="328" y="156" text-anchor="middle">dm-linear, dm-crypt, dm-zoned</text><rect class="box" x="460" y="132" width="280" height="40" rx="6" /><text class="xs" x="600" y="156" text-anchor="middle">pass zones through; dm-zoned hides them</text><line class="lna" x1="128" y1="172" x2="128.0" y2="176.0"/><polygon class="ah" points="128.0,184.0 123.5,175.0 132.5,175.0"/><rect class="dl" x="60" y="184" width="136" height="40" rx="6" /><text class="s h" x="128" y="208" text-anchor="middle">Block layer</text><rect class="box" x="206" y="184" width="244" height="40" rx="6" /><text class="xs" x="328" y="208" text-anchor="middle">zone write plugging</text><rect class="box" x="460" y="184" width="280" height="40" rx="6" /><text class="xs" x="600" y="208" text-anchor="middle">orders writes per zone, tracks WP</text><line class="lna" x1="128" y1="224" x2="128.0" y2="228.0"/><polygon class="ah" points="128.0,236.0 123.5,227.0 132.5,227.0"/><rect class="dl" x="60" y="236" width="136" height="40" rx="6" /><text class="s h" x="128" y="260" text-anchor="middle">NVMe driver</text><rect class="box" x="206" y="236" width="244" height="40" rx="6" /><text class="xs" x="328" y="260" text-anchor="middle">nvme</text><rect class="box" x="460" y="236" width="280" height="40" rx="6" /><text class="xs" x="600" y="260" text-anchor="middle">Identify to limits, Report Zones</text><line class="lna" x1="128" y1="276" x2="128.0" y2="280.0"/><polygon class="ah" points="128.0,288.0 123.5,279.0 132.5,279.0"/><rect class="pl" x="60" y="288" width="136" height="40" rx="6" /><text class="s h" x="128" y="312" text-anchor="middle">ZNS SSD</text><rect class="box" x="206" y="288" width="244" height="40" rx="6" /><text class="xs" x="328" y="312" text-anchor="middle">firmware</text><rect class="box" x="460" y="288" width="280" height="40" rx="6" /><text class="xs" x="600" y="312" text-anchor="middle">enforces WP, states, MAR/MOR</text><polyline class="lnd" points="60,40 24,40 24,256 50.0,256.0"/><polygon class="ahd" points="58.0,256.0 49.0,260.5 49.0,251.5"/><polyline class="lnd" points="60,58 40,58 40,308 50.0,308.0"/><polygon class="ahd" points="58.0,308.0 49.0,312.5 49.0,303.5"/><text class="xs d" x="20" y="344" text-anchor="start">Dashed: NVMe passthrough (/dev/ng char device, io_uring cmd) reaches the driver without the block layer;</text><text class="xs d" x="20" y="358" text-anchor="start">SPDK and similar user-space drivers reach the device directly. Then write ordering is the caller's job.</text><text class="xs d" x="20" y="376" text-anchor="start">Amber: layers above the block layer. Blue: block layer and NVMe driver. Green: device, the last line of defense.</text></svg>`};
DIAGRAMS.zplan={title:'ZNS validation phases and gates',cap:'Phases run in dependency order and are grouped by how often they run: the first four as a fast gate on every build, the middle three nightly, and the long-running phases weekly and before release.',svg:`<svg viewBox="0 0 760 370" role="img" aria-label="Eleven ZNS validation phases grouped into smoke, nightly and weekly gates in dependency order"><title>Eleven ZNS validation phases grouped into smoke, nightly and weekly gates in dependency order</title><rect class="grp" x="20" y="14" width="720" height="92" rx="6" /><text class="s h" x="34" y="32" text-anchor="start">Smoke gate: every firmware build, minutes</text><rect class="pl" x="30" y="44" width="166" height="48" rx="4" /><text class="xs d" x="113" y="64" text-anchor="middle">Phase 0</text><text class="s h" x="113" y="81" text-anchor="middle">Profile</text><line class="ln" x1="196" y1="68" x2="200.0" y2="68.0"/><polygon class="ahd" points="208.0,68.0 199.0,72.5 199.0,63.5"/><rect class="pl" x="208" y="44" width="166" height="48" rx="4" /><text class="xs d" x="291" y="64" text-anchor="middle">Phase 1</text><text class="s h" x="291" y="81" text-anchor="middle">Static</text><line class="ln" x1="374" y1="68" x2="378.0" y2="68.0"/><polygon class="ahd" points="386.0,68.0 377.0,72.5 377.0,63.5"/><rect class="pl" x="386" y="44" width="166" height="48" rx="4" /><text class="xs d" x="469" y="64" text-anchor="middle">Phase 2</text><text class="s h" x="469" y="81" text-anchor="middle">State machine</text><line class="ln" x1="552" y1="68" x2="556.0" y2="68.0"/><polygon class="ahd" points="564.0,68.0 555.0,72.5 555.0,63.5"/><rect class="pl" x="564" y="44" width="166" height="48" rx="4" /><text class="xs d" x="647" y="64" text-anchor="middle">Phase 3</text><text class="s h" x="647" y="81" text-anchor="middle">I/O rules</text><line class="lna" x1="380" y1="106" x2="380.0" y2="114.0"/><polygon class="ah" points="380.0,122.0 375.5,113.0 384.5,113.0"/><rect class="grp" x="20" y="122" width="720" height="92" rx="6" /><text class="s h" x="34" y="140" text-anchor="start">Nightly</text><rect class="dl" x="30" y="152" width="225" height="48" rx="4" /><text class="xs d" x="143" y="172" text-anchor="middle">Phase 4</text><text class="s h" x="143" y="189" text-anchor="middle">Resources</text><line class="ln" x1="255" y1="176" x2="259.0" y2="176.0"/><polygon class="ahd" points="267.0,176.0 258.0,180.5 258.0,171.5"/><rect class="dl" x="267" y="152" width="225" height="48" rx="4" /><text class="xs d" x="380" y="172" text-anchor="middle">Phase 5</text><text class="s h" x="380" y="189" text-anchor="middle">Append</text><line class="ln" x1="493" y1="176" x2="497.0" y2="176.0"/><polygon class="ahd" points="505.0,176.0 496.0,180.5 496.0,171.5"/><rect class="dl" x="505" y="152" width="225" height="48" rx="4" /><text class="xs d" x="617" y="172" text-anchor="middle">Phase 6</text><text class="s h" x="617" y="189" text-anchor="middle">Persistence</text><line class="lna" x1="380" y1="214" x2="380.0" y2="222.0"/><polygon class="ah" points="380.0,230.0 375.5,221.0 384.5,221.0"/><rect class="grp" x="20" y="230" width="720" height="92" rx="6" /><text class="s h" x="34" y="248" text-anchor="start">Weekly and release gate</text><rect class="tl" x="30" y="260" width="166" height="48" rx="4" /><text class="xs d" x="113" y="280" text-anchor="middle">Phase 7</text><text class="s h" x="113" y="297" text-anchor="middle">Integrity, soak</text><line class="ln" x1="196" y1="284" x2="200.0" y2="284.0"/><polygon class="ahd" points="208.0,284.0 199.0,288.5 199.0,279.5"/><rect class="tl" x="208" y="260" width="166" height="48" rx="4" /><text class="xs d" x="291" y="280" text-anchor="middle">Phase 8</text><text class="s h" x="291" y="297" text-anchor="middle">Faults</text><line class="ln" x1="374" y1="284" x2="378.0" y2="284.0"/><polygon class="ahd" points="386.0,284.0 377.0,288.5 377.0,279.5"/><rect class="tl" x="386" y="260" width="166" height="48" rx="4" /><text class="xs d" x="469" y="280" text-anchor="middle">Phase 9</text><text class="s h" x="469" y="297" text-anchor="middle">Performance</text><line class="ln" x1="552" y1="284" x2="556.0" y2="284.0"/><polygon class="ahd" points="564.0,284.0 555.0,288.5 555.0,279.5"/><rect class="tl" x="564" y="260" width="166" height="48" rx="4" /><text class="xs d" x="647" y="280" text-anchor="middle">Phase 10</text><text class="s h" x="647" y="297" text-anchor="middle">Host stack</text><text class="xs d" x="20" y="344" text-anchor="start">Arrows show dependency: a broken Reset or Report Zones in an early phase invalidates every later result,</text><text class="xs d" x="20" y="358" text-anchor="start">so later phases run only when earlier ones pass. Expected values come from the spec tables, not the device.</text></svg>`};
DIAGRAMS.zstore={title:'Host log-structured store on ZNS',cap:'The store separates writes by expected lifetime so zones empty together, keeps its own index from objects to zone offsets, reclaims space by copying live data out of a victim zone and resetting it, and rebuilds state after a crash by scanning each zone up to its write pointer.',svg:`<svg viewBox="0 0 760 372" role="img" aria-label="Components of a host-managed log-structured store on a ZNS SSD and the work the device still does"><title>Components of a host-managed log-structured store on a ZNS SSD and the work the device still does</title><rect class="tl" x="20" y="10" width="720" height="36" rx="6" /><text class="h" x="380" y="33" text-anchor="middle">Application writes objects</text><line class="lna" x1="380" y1="46" x2="380.0" y2="56.0"/><polygon class="ah" points="380.0,64.0 375.5,55.0 384.5,55.0"/><rect class="grp" x="20" y="64" width="720" height="50" rx="6" /><text class="s h" x="34" y="80" text-anchor="start">Placement by expected lifetime (one open zone per stream)</text><rect class="tl" x="34" y="86" width="164" height="22" rx="3" /><text class="xs h" x="116" y="101" text-anchor="middle">WAL</text><rect class="tl" x="210" y="86" width="164" height="22" rx="3" /><text class="xs h" x="292" y="101" text-anchor="middle">hot</text><rect class="tl" x="386" y="86" width="164" height="22" rx="3" /><text class="xs h" x="468" y="101" text-anchor="middle">cold</text><rect class="tl" x="562" y="86" width="164" height="22" rx="3" /><text class="xs h" x="644" y="101" text-anchor="middle">GC output</text><line class="lna" x1="380" y1="114" x2="380.0" y2="124.0"/><polygon class="ah" points="380.0,132.0 375.5,123.0 384.5,123.0"/><text class="s h" x="34" y="148" text-anchor="start">Zones</text><rect class="tl" x="90" y="134" width="72" height="30" rx="3" /><text class="xs" x="126" y="153" text-anchor="middle">open</text><rect class="tl" x="172" y="134" width="72" height="30" rx="3" /><text class="xs" x="208" y="153" text-anchor="middle">open</text><rect class="dl" x="254" y="134" width="72" height="30" rx="3" /><text class="xs" x="290" y="153" text-anchor="middle">full</text><rect class="dl" x="336" y="134" width="72" height="30" rx="3" /><text class="xs" x="372" y="153" text-anchor="middle">full</text><rect class="dl" x="418" y="134" width="72" height="30" rx="3" /><text class="xs" x="454" y="153" text-anchor="middle">full</text><rect class="box" x="500" y="134" width="72" height="30" rx="3" /><text class="xs" x="536" y="153" text-anchor="middle">empty</text><rect class="box" x="582" y="134" width="72" height="30" rx="3" /><text class="xs" x="618" y="153" text-anchor="middle">empty</text><rect class="er" x="664" y="134" width="72" height="30" rx="3" /><text class="xs" x="700" y="153" text-anchor="middle">victim</text><rect class="tl" x="20" y="186" width="162" height="66" rx="6" /><text class="s h" x="101" y="205" text-anchor="middle">Index</text><text class="xs d" x="101" y="222" text-anchor="middle">object -&gt; zone,</text><text class="xs d" x="101" y="237" text-anchor="middle">offset, length</text><rect class="tl" x="206" y="186" width="162" height="66" rx="6" /><text class="s h" x="287" y="205" text-anchor="middle">Zone allocator</text><text class="xs d" x="287" y="222" text-anchor="middle">Empty pool from</text><text class="xs d" x="287" y="237" text-anchor="middle">Report Zones; MAR/MOR</text><rect class="tl" x="392" y="186" width="162" height="66" rx="6" /><text class="s h" x="473" y="205" text-anchor="middle">Host GC</text><text class="xs d" x="473" y="222" text-anchor="middle">live bytes per zone:</text><text class="xs d" x="473" y="237" text-anchor="middle">copy live, then Reset</text><rect class="tl" x="578" y="186" width="162" height="66" rx="6" /><text class="s h" x="659" y="205" text-anchor="middle">Recovery</text><text class="xs d" x="659" y="222" text-anchor="middle">checkpoint, then scan</text><text class="xs d" x="659" y="237" text-anchor="middle">each zone up to WP</text><polyline class="lnr" points="700,164 700,175 500,175 500.0,178.0"/><polygon class="ahr" points="500.0,186.0 495.5,177.0 504.5,177.0"/><text class="xs d" x="473" y="270" text-anchor="middle">after Reset the victim zone joins the Empty pool</text><rect class="pl" x="20" y="296" width="720" height="46" rx="6" /><text class="s h" x="380" y="315" text-anchor="middle">Device keeps media management</text><text class="xs d" x="380" y="332" text-anchor="middle">ECC and parity, bad blocks, wear and refresh inside zones, write pointer and state enforcement</text><text class="xs d" x="20" y="360" text-anchor="start">Amber: jobs the host store now owns (the FTL did them on a conventional SSD). Green: still done by the device.</text></svg>`};
